import React from 'react';

export function OrbMain() {
  return (
    <>
      {/* outer glow */}
      <div style={{
        position: 'absolute', left: '50%', transform: 'translateX(-50%)',
        width: 360, height: 360, top: 100,
        borderRadius: '50%', pointerEvents: 'none',
        background: 'radial-gradient(circle at 40% 40%, rgba(126,200,200,0.35) 0%, rgba(45,107,107,0.12) 55%, transparent 75%)',
        filter: 'blur(32px)',
        animation: 'orbFloat 10s ease-in-out infinite reverse',
      }} />
      {/* main orb */}
      <div style={{
        position: 'absolute', left: '50%', transform: 'translateX(-50%)',
        width: 240, height: 240, top: 130,
        borderRadius: '50%', pointerEvents: 'none',
        background: 'radial-gradient(circle at 38% 35%, #7EC8C8 0%, #2D6B6B 45%, #1A3A3A 100%)',
        boxShadow: '0 0 100px rgba(45,107,107,0.4), 0 0 40px rgba(126,200,200,0.15)',
        animation: 'orbFloat 8s ease-in-out infinite',
      }} />
    </>
  );
}

export function OrbSmall({ style = {} }) {
  return (
    <div style={{
      width: 72, height: 72, borderRadius: '50%', flexShrink: 0,
      background: 'radial-gradient(circle at 38% 35%, #7EC8C8, #2D6B6B)',
      boxShadow: '0 0 40px rgba(45,107,107,0.35)',
      animation: 'orbFloatFree 6s ease-in-out infinite',
      ...style,
    }} />
  );
}

// OrbBreathing — identical visuals to OrbMain.
// Scale is driven by a JS ref + CSS transition so it follows the countdown smoothly.
// phase: 0=in, 1=hold, 2=out   count: seconds remaining   totalSecs: phase duration
export function OrbBreathing({ phase, count, totalSecs, running }) {
  const ref = React.useRef(null);

  React.useEffect(() => {
    const el = ref.current;
    if (!el) return;

    if (!running) {
      // idle — gentle pulse via CSS animation
      el.style.transition = 'none';
      el.style.transform = 'scale(1)';
      el.style.animation = 'orbIdlePulse 5s ease-in-out infinite';
      return;
    }

    // Remove CSS animation so we can control transform directly
    el.style.animation = 'none';

    // Progress through the phase: 0 at start → 1 at end
    // count goes from totalSecs down to 0
    const elapsed = totalSecs - count;
    const progress = totalSecs > 0 ? elapsed / totalSecs : 0;

    let targetScale;
    if (phase === 0) {
      // Breathe in: scale 1 → 1.45 over full phase
      targetScale = 1 + progress * 0.45;
    } else if (phase === 1) {
      // Hold: stay at 1.45
      targetScale = 1.45;
    } else {
      // Breathe out: scale 1.45 → 0.92 over full phase
      targetScale = 1.45 - progress * 0.53;
    }

    // Transition duration = 1 tick (1s) with smooth easing so each step glides
    el.style.transition = 'transform 1.05s cubic-bezier(0.45, 0, 0.55, 1)';
    el.style.transform = `scale(${targetScale.toFixed(3)})`;
  }, [phase, count, running, totalSecs]);

  // Inject idle keyframe once
  if (typeof document !== 'undefined' && !document.getElementById('orb-idle-kf')) {
    const s = document.createElement('style');
    s.id = 'orb-idle-kf';
    s.textContent = '@keyframes orbIdlePulse { 0%,100%{transform:scale(1)} 50%{transform:scale(1.06)} }';
    document.head.appendChild(s);
  }

  return (
    <div style={{ position: 'relative', width: 240, height: 240, flexShrink: 0 }}>
      {/* outer glow */}
      <div style={{
        position: 'absolute',
        width: 360, height: 360,
        top: '50%', left: '50%',
        transform: 'translate(-50%, -50%)',
        borderRadius: '50%', pointerEvents: 'none',
        background: 'radial-gradient(circle at 40% 40%, rgba(126,200,200,0.35) 0%, rgba(45,107,107,0.12) 55%, transparent 75%)',
        filter: 'blur(32px)',
      }} />
      {/* main orb */}
      <div
        ref={ref}
        style={{
          width: 240, height: 240,
          borderRadius: '50%',
          background: 'radial-gradient(circle at 38% 35%, #7EC8C8 0%, #2D6B6B 45%, #1A3A3A 100%)',
          boxShadow: '0 0 100px rgba(45,107,107,0.4), 0 0 40px rgba(126,200,200,0.15)',
          transformOrigin: 'center center',
          position: 'relative', zIndex: 1,
        }}
      />
    </div>
  );
}
